output_text:
[
  {
    "id": "pedestrian_only_single_file_aisles",
    "text": "Single-file shelf aisles are pedestrian-only, so a shopper must not have a cart in cells whose horizontal clearance is only one cell.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "single_file_aisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper may not push a cart into a single-file aisle and must instead leave it at the aisle mouth.",
    "abstraction": {
      "state_properties": {
        "single_file_aisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "recover_parked_cart",
    "text": "Whenever a shopper parks a cart to enter an aisle, they are obliged to recover the cart before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "recover_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart",
      "discharge": "recover_cart"
    }
  },
  {
    "id": "park_only_at_wide_junctions",
    "text": "Carts may only be parked at wide open junctions or at the entrance cart area, not in shelf-adjacent or constricted spaces.",
    "abstraction": {
      "state_properties": {
        "wide_open_junction": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "cart_depot": "at(1,7)",
        "authorized_cart_parking_place": {
          "or": [
            "wide_open_junction",
            "cart_depot"
          ]
        }
      },
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "park_cart",
          {
            "not": "authorized_cart_parking_place"
          }
        ]
      }
    }
  },
  {
    "id": "interact_only_at_shelves_or_cart_zones",
    "text": "Interactions should occur only at shelf-access cells or at recognized cart-handling zones such as the entrance and wide junctions.",
    "abstraction": {
      "state_properties": {
        "wide_open_junction": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "cart_depot": "at(1,7)",
        "cart_handling_zone": {
          "or": [
            "cart_depot",
            "wide_open_junction"
          ]
        },
        "legitimate_interaction_place": {
          "or": [
            "adjShelf",
            "cart_handling_zone"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "legitimate_interaction_place"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_north_in_pinches",
    "text": "When pushing a cart through a vertically pinched lower-aisle cell, the shopper must not move north into the shelf bottleneck.",
    "abstraction": {
      "state_properties": {
        "vertical_pinch_with_cart": {
          "and": [
            "hasCart",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "vertical_pinch_with_cart",
          "N"
        ]
      }
    }
  },
  {
    "id": "step_away_after_shelf_interact",
    "text": "After taking an item from a shelf, the shopper is obliged to make a move away from the shelf face they interacted with.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "shelf_interaction": {
          "pre": {
            "and": [
              "adjShelf",
              "INTERACT"
            ]
          },
          "post": null
        },
        "move_away_from_shelf": {
          "pre": {
            "or": [
              {
                "and": [
                  "shelfN",
                  "S"
                ]
              },
              {
                "and": [
                  "shelfS",
                  "N"
                ]
              },
              {
                "and": [
                  "shelfE",
                  "W"
                ]
              },
              {
                "and": [
                  "shelfW",
                  "E"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "shelf_interaction",
      "discharge": "move_away_from_shelf"
    }
  },
  {
    "id": "no_westbound_cart_flow",
    "text": "Shopping carts should follow the store's one-way flow toward the exit, so pushing a cart west is forbidden.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "W"
        ]
      }
    }
  }
]
